INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Umsatz allein den Erfolg eines IT-Projekts zeigt?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten müssen berücksichtigt werden"}, {"text": "Ja", "correct": false, "because": "Ohne Kosten keine Gewinnermittlung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, um die Rentabilität eines Projekts zu prüfen?', 3, '[{"text": "Differenz zwischen Einnahmen und Ausgaben", "correct": true, "because": "Zeigt tatsächlichen Gewinn"}, {"text": "Hoher Umsatz", "correct": false, "because": "Ignoriert Kosten"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Kein finanzieller Indikator"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten muss ich bei einem Serverkauf berücksichtigen?', 5, '[{"text": "Anschaffungskosten", "correct": true, "because": "Grundpreis des Geräts"}, {"text": "Betriebskosten", "correct": true, "because": "Strom und Wartung"}, {"text": "Marketingkosten", "correct": false, "because": "Nicht direkt relevant"}, {"text": "Büromiete", "correct": false, "because": "Separat kalkuliert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Fixkosten bleiben bei Produktionsänderung gleich. b) Variable Kosten sind immer höher.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Variable Kosten hängen von Produktion ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich die Kosten für eine Softwareentwicklung berechne?', 4, '[{"text": "Lizenzgebühren", "correct": false, "because": "Teil der Gesamtkosten"}, {"text": "Entwicklungszeit", "correct": false, "because": "Arbeitsstunden zählen"}, {"text": "Farbe der Benutzeroberfläche", "correct": true, "because": "Kein Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass hohe Ausgaben immer zu Verlusten führen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Einnahmen können Ausgaben übersteigen"}, {"text": "Ja", "correct": false, "because": "Gewinn hängt von Differenz ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um die Wirtschaftlichkeit eines IT-Systems zu prüfen?', 3, '[{"text": "Kosten-Nutzen-Analyse", "correct": true, "because": "Vergleicht Aufwand und Ertrag"}, {"text": "Zufällige Schätzung", "correct": false, "because": "Ungenau und unzuverlässig"}, {"text": "Marktpreisvergleich", "correct": false, "because": "Nur ein Teilaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen den Ertrag eines IT-Projekts?', 5, '[{"text": "Vertragsvolumen", "correct": true, "because": "Bestimmt Einnahmen"}, {"text": "Effiziente Ressourcennutzung", "correct": true, "because": "Senkt Kosten"}, {"text": "Büroausstattung", "correct": false, "because": "Indirekter Einfluss"}, {"text": "Teamgröße", "correct": false, "because": "Nicht allein entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Abschreibungen die Liquidität beeinflussen und b) sie direkte Kosten sind. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Abschreibungen sind keine Zahlung, keine direkten Kosten"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um die Kosten eines Netzwerkausbaus zu ermitteln?', 4, '[{"text": "Hardwarepreise", "correct": false, "because": "Teil der Investition"}, {"text": "Installationsaufwand", "correct": false, "because": "Arbeitszeit zählt"}, {"text": "Kundendienstzeiten", "correct": true, "because": "Nachgelagerter Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Gemeinkosten immer fix?', 2, '[{"text": "Nein", "correct": true, "because": "Können auch variabel sein"}, {"text": "Ja", "correct": false, "because": "Abhängig von Verbrauch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenarten fallen bei einem Cloud-Projekt an?', 4, '[{"text": "Nutzungsgebühren", "correct": true, "because": "Basieren auf Verbrauch"}, {"text": "Supportkosten", "correct": true, "because": "Für Wartung und Hilfe"}, {"text": "Büromöbel", "correct": false, "because": "Nicht projektspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein hoher Umsatz immer profitabel ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten können Einnahmen übersteigen"}, {"text": "Ja", "correct": false, "because": "Gewinn zählt, nicht Umsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich die Kosten eines IT-Projekts plane?', 3, '[{"text": "Transparente Kostenaufstellung", "correct": true, "because": "Ermöglicht Kontrolle"}, {"text": "Schnelle Fertigstellung", "correct": false, "because": "Qualität wichtiger"}, {"text": "Maximale Ausgaben", "correct": false, "because": "Keine Zielsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Materialkosten sind variable Kosten. b) Miete ist eine variable Kostenart.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Miete ist fix"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft mir, den Break-even-Punkt eines Projekts zu finden?', 4, '[{"text": "Deckungsbeitragsrechnung", "correct": true, "because": "Zeigt Gewinnschwelle"}, {"text": "Zufallsschätzung", "correct": false, "because": "Ungenau"}, {"text": "Marktanalyse", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob indirekte Kosten immer schwer zuzuordnen sind?', 2, '[{"text": "Ja", "correct": true, "because": "Nicht direkt projektbezogen"}, {"text": "Nein", "correct": false, "because": "Zuordnung oft komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten beeinflussen die Rentabilität eines IT-Dienstes?', 5, '[{"text": "Personalkosten", "correct": true, "because": "Hauptanteil der Ausgaben"}, {"text": "Wartungskosten", "correct": true, "because": "Beeinflussen Betrieb"}, {"text": "Kundenzufriedenheit", "correct": false, "because": "Indirekter Einfluss"}, {"text": "Bürogestaltung", "correct": false, "because": "Nicht primär relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Gewinn immer gleich dem Umsatz?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten werden abgezogen"}, {"text": "Ja", "correct": false, "because": "Umsatz enthält keine Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenart ist bei einer Softwarelizenz entscheidend?', 3, '[{"text": "Fixkosten", "correct": true, "because": "Einmalige oder regelmäßige Gebühr"}, {"text": "Variable Kosten", "correct": false, "because": "Nutzungsabhängig selten"}, {"text": "Indirekte Kosten", "correct": false, "because": "Nicht primär zutreffend"}]');
